class Solution {
    bool findPath(TreeNode* node, int target, string& path) {
        if (!node) return false;
        if (node->val == target) return true;
        path.push_back('L');
        if (findPath(node->left, target, path)) return true;
        path.pop_back();
        path.push_back('R');
        if (findPath(node->right, target, path)) return true;
        path.pop_back();
        return false;
    }
public:
    string getDirections(TreeNode* root, int startValue, int destValue) {
        string pathS, pathT;
        findPath(root, startValue, pathS);
        findPath(root, destValue, pathT);
        int i = 0;
        while (i < (int)pathS.size() && i < (int)pathT.size() && pathS[i] == pathT[i]) i++;
        string result;
        result.reserve((pathS.size() - i) + (pathT.size() - i));
        for (int j = i; j < (int)pathS.size(); j++) result += 'U';
        result += pathT.substr(i);
        return result;
    }
};
